// Identifica o circuito pelo proprio topico MQTT: iot/residencial/<circuito>/consumo
const parts = (msg.topic || '').split('/');
const circuito = parts[2]; // 'tomadas' ou 'lampadas'
if (circuito !== 'tomadas' && circuito !== 'lampadas') {
  node.warn('topico inesperado: ' + msg.topic);
  return null;
}

const watts = parseFloat(msg.payload);
if (isNaN(watts)) { node.warn('payload invalido em ' + circuito); return null; }

// Estado por circuito (variaveis sufixadas)
const agora = Date.now();
const ultimo  = flow.get('ultimoTs_' + circuito) || agora;
const kwhAcum = flow.get('kwhAcum_' + circuito) || 0;
const deltaH  = (agora - ultimo) / 3600000;
const novoKwh = kwhAcum + (watts * deltaH) / 1000;
flow.set('ultimoTs_' + circuito, agora);
flow.set('kwhAcum_' + circuito, novoKwh);
flow.set('ultimoWatts_' + circuito, watts);

const TARIFA = 0.95;        // R$/kWh - ajustar conforme a concessionaria
const TENSAO_V = 127;        // V (tensao nominal residencial - Sao Paulo)
const corrente = watts / TENSAO_V;
let status = 'normal';
if (watts > 2000) status = 'critico';
else if (watts > 1200) status = 'alto';
flow.set('status_' + circuito, status);

// formato InfluxDB v2: [fields, tags]
msg.payload = [
  { watts: watts, corrente_a: corrente, tensao_v: TENSAO_V, kwh: novoKwh, custo_brl: novoKwh * TARIFA, status: status },
  { circuito: circuito }
];
msg.circuito = circuito; // propaga para os proximos nos (regra pico)
return msg;

const circuito = msg.circuito;
if (!circuito) return null;
const w = flow.get('ultimoWatts_' + circuito);
if (typeof w !== 'number') return null;

const LIMITE_W  = 2000;
const JANELA_MS = 5 * 60 * 1000;
const agora = Date.now();
const K_INI = 'inicioPico_' + circuito;
const K_ALR = 'alertaPicoEnviado_' + circuito;

let inicioPico = flow.get(K_INI) || 0;

if (w > LIMITE_W) {
  if (inicioPico === 0) {
    flow.set(K_INI, agora);
  } else if (agora - inicioPico > JANELA_MS && !flow.get(K_ALR)) {
    flow.set(K_ALR, true);
    const CHAT_ID = parseInt(env.get('TELEGRAM_CHAT_ID') || '675744903');
    const topicoCmd = 'iot/residencial/' + circuito + '/comando';
    return [
      { payload: 'OFF', topic: topicoCmd, circuito: circuito, motivo: 'pico' },
      { payload: { chatId: CHAT_ID, type: 'message', content: 'Pico de ' + w.toFixed(0) + ' W sustentado por mais de 5 min no circuito ' + circuito + ' - desligando o disjuntor.' } }
    ];
  }
} else {
  flow.set(K_INI, 0);
  flow.set(K_ALR, false);
}
return null;

const JANELA_MS = 30 * 60 * 1000;
const agora = Date.now();
const circuitos = ['tomadas', 'lampadas'];
const out = [];

for (const c of circuitos) {
  const w = flow.get('ultimoWatts_' + c) || 0;
  const K_INI = 'inicioStb_' + c;
  const K_ALR = 'stbAlerta_' + c;
  let inicioStb = flow.get(K_INI) || 0;

  if (w >= 5 && w <= 15) {
    if (inicioStb === 0) flow.set(K_INI, agora);
    else if (agora - inicioStb > JANELA_MS && !flow.get(K_ALR)) {
      flow.set(K_ALR, true);
      const CHAT_ID = parseInt(env.get('TELEGRAM_CHAT_ID') || '675744903');
      out.push({ payload: { chatId: CHAT_ID, type: 'message', content: 'Consumo de ' + w.toFixed(1) + ' W ha mais de 30 min no circuito ' + c + ' - possivel stand-by. Sugiro desligar.' } });
    }
  } else {
    flow.set(K_INI, 0);
    flow.set(K_ALR, false);
  }
}
return [out];

const circuito = 'lampadas';
const acao = msg.payload;
msg.topic = 'iot/residencial/' + circuito + '/comando';
msg.payload = acao;
msg.circuito = circuito;
msg.motivo = 'horario programado';
return msg;

// circuito vem de msg.circuito (passado pelas funcoes upstream)
const circuito = msg.circuito || 'desconhecido';
const acao = msg.payload;
// formato InfluxDB v2: [fields, tags]
msg.payload = [
  { acao: acao, motivo: msg.motivo || 'automatico' },
  { circuito: circuito }
];
return msg;
